layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 400; font-style: normal; line-height: 1.75; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="footer"] { color: var(--ryt-border); background-color: rgb(20, 20, 23); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { background-color: var(--ryt-bg); border-top: 1px solid var(--ryt-border); border-right: 1px solid var(--ryt-border); border-bottom: 1px solid var(--ryt-border); border-left: 1px solid var(--ryt-border); border-radius: 16px; box-shadow: rgba(20, 42, 54, 0.08) 0px 2px 8px 0px; transition: transform 0.32s cubic-bezier(0.22, 0.61, 0.36, 1), box-shadow 0.32s cubic-bezier(0.22, 0.61, 0.36, 1) }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: 2px; transition: all }
[data-ryt="section"] > h2 { color: rgb(20, 20, 23); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; line-height: 1.15; letter-spacing: -0.96px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(20, 20, 23); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="button"] { color: var(--ryt-accent); background-color: rgb(253, 247, 231); border-top: 1px solid var(--ryt-muted); border-right: 1px solid var(--ryt-muted); border-bottom: 1px solid var(--ryt-muted); border-left: 1px solid var(--ryt-muted); border-radius: 800px; font-family: var(--ryt-font-heading); font-weight: 500; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 4.8px; padding-right: 12.8px; padding-bottom: 4.8px; padding-left: 12.8px; transition: all }
[data-ryt="header"] { border-bottom: 1px solid var(--ryt-border); border-top: none }
[data-ryt="nav"] a { color: var(--ryt-text); border-radius: 800px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 500; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 14.4px; padding-bottom: 8px; padding-left: 14.4px; transition: all }
[data-ryt="review"] { color: rgb(97, 114, 124); font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(97, 114, 124); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: Quantico, Inter, system-ui, sans-serif; font-size: 12px; font-weight: 700; font-style: normal; line-height: 1.6; letter-spacing: 1.44px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="cover"] { border-radius: 0px }
[data-ryt="rec-card"] [data-ryt="title"] a { color: rgb(20, 20, 23); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 600; font-style: normal; letter-spacing: -0.44px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(20, 20, 23); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: rgb(20, 20, 23); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 22px; font-weight: 600; font-style: normal; line-height: 1.3; letter-spacing: -0.44px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(20, 20, 23); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: #a16207; color: #a16207 }
[data-ryt="cover"]:hover { transform: scale(1.04) }
[data-ryt="nav"] a:hover { color: #a16207; color: #a16207 }
[data-ryt="button"]:hover { color: #713f12 }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: #a16207 }
article[data-ryt="rec-card"]:hover { transform: translateY(-4px); box-shadow: 0 16px 40px rgba(20, 42, 54, 0.14) }
